from threetears.evals import Eval

from importer import read_statement_file


def dates(case):
    """The dates the importer gives the statement's transactions with this description and amount."""
    found = read_statement_file("data/" + case["statement"])
    return {"dates": [t.date.isoformat() for t in found if t.description == case["description"] and t.pence == case["pence"]]}


def dated_as_ledger(case, out):
    """The transaction imports on the date the hand-kept ledger has."""
    return case["date"] in out["dates"]


ledger = Eval("data/ledger.jsonl", runner=dates, grader=[dated_as_ledger], k=1)
